  TH.LYFT = { span: ['19:00', '26:00'], hoursText: TH.TRANSPORT.lyft.hoursText, zone: TH.TRANSPORT.lyft.boundary.text, monthlyCapUSD: TH.TRANSPORT.lyft.monthlyCapUSD, url: TH.TRANSPORT.lyft.url };
  // ---------- USC bus times ----------
  // TH.busTimes(busId, stopIdx, dateOrDay) -> sorted minutes-of-day with a published departure at that stop.
  // dateOrDay: Date, 'YYYY-MM-DD' or weekday 0..6. [] when the route does not run that day (weekday, university holiday, noService date).
  // opts.est: also include the START of each window USC publishes only as "estimated times" (Union Station → UPC, 3–7 PM).
  // Without it the result is the fixed published trips only (js/core.js TH.busDepartures adds the windows itself).
  function busRuns(bus, dateOrDay) {
    const T = TH.TRANSPORT; let wd, key = null;
    if (typeof dateOrDay === 'number') wd = dateOrDay;
    else if (dateOrDay == null) { const n = new Date(); wd = n.getDay(); key = dkey(n); }
    else { wd = dow(dateOrDay); key = dkey(dateOrDay); }
    if (!bus.days.includes(wd)) return false;
    return !(key && (T.holidays.includes(key) || (bus.noService || []).includes(key)));
  }
  // The result always carries `.estimated`: USC's estimated windows for that stop/day as [{at, end, estimated:true}]
  // (non-enumerable, so callers that merge the windows themselves, e.g. core.js TH.busDepartures, never double them).
  TH.busTimes = function (busId, stopIdx, dateOrDay, opts) {
    const all = TH.busTrips(busId, stopIdx, dateOrDay), out = all.filter(x => !x.estimated || (opts && opts.est)).map(x => x.at);
    Object.defineProperty(out, 'estimated', { value: all.filter(x => x.estimated), enumerable: false });
    return out;
  };
  // TH.busTrips(busId, stopIdx, dateOrDay) -> [{at, end?, estimated?}] sorted by `at` (minutes of day):
  // fixed published trips plus USC's estimated windows ({at: window start, end: window end, estimated: true}; show as "est.").
  TH.busTrips = function (busId, stopIdx, dateOrDay) {
    const bus = TH.TRANSPORT.buses.find(b => b.id === busId); if (!bus || !busRuns(bus, dateOrDay)) return [];
    const k = String(stopIdx || 0), out = ((bus.trips && bus.trips[k]) || []).map(x => ({ at: t(x) }));
    ((bus.estTrips && bus.estTrips[k]) || []).forEach(x => out.push({ at: t(x.at), end: t(x.end), estimated: true }));
    return out.sort((a, b) => a.at - b.at);
  };
  // Next departures after minute-of-day `fromMin` (default: now), incl. estimated windows still open. -> [{busId, name, stop, at, end?, est, inMin}]
  TH.nextBuses = function (stopPlaceId, date, fromMin, n) {
    const d = date || new Date(), m = fromMin == null ? d.getHours() * 60 + d.getMinutes() : fromMin, out = [];
    TH.TRANSPORT.buses.forEach(b => b.stops.forEach((s, i) => {
      if (s.placeId !== stopPlaceId) return;
      TH.busTrips(b.id, i, d).filter(x => (x.estimated ? x.end : x.at) >= m).slice(0, n || 3).forEach(x => out.push({ busId: b.id, name: b.name, short: b.short, color: b.color, stop: i, at: x.at, end: x.end, est: !!x.estimated, estimated: !!x.estimated, inMin: Math.max(0, x.at - m) }));
    }));
    return out.sort((a, b) => a.at - b.at).slice(0, n || 6);
  };

  // ---------- safety info ----------
  TH.SAFETY = {"phones":[{"label":"DPS emergency (UPC and USC Village)","number":"(213) 740-4321","note":"24/7/365","url":"https://dps.usc.edu/contact/"},{"label":"DPS non-emergency (UPC and USC Village)","number":"(213) 740-6000","note":"24/7","url":"https://dps.usc.edu/contact/"},{"label":"DPS emergency (HSC)","number":"(323) 442-1000","note":"24/7","url":"https://dps.usc.edu/contact/"},{"label":"DPS non-emergency (HSC)","number":"(323) 442-1200","note":"24/7","url":"https://dps.usc.edu/contact/"},{"label":"DPS USC Village sub-station","number":"(213) 821-6677","note":null,"url":"https://dps.usc.edu/contact/"},{"label":"DPS Lost and Found (UPC)","number":"(213) 740-9759","note":"lostandfound@dps.usc.edu","url":"https://dps.usc.edu/contact/"},{"label":"DPS bike registration questions","number":"(213) 740-5519","note":null,"url":"https://dps.usc.edu/contact/"},{"label":"DPS Watch Commanders' Office","number":"(213) 740-5523","note":null,"url":"https://dps.usc.edu/contact/"},{"label":"Off-campus emergency","number":"911","note":null,"url":"https://dps.usc.edu/contact/"},{"label":"USC Student Health 24/7 (nurse, counselor, confidential advocate)","number":"(213) 740-9355 (WELL)","note":null,"url":"https://studenthealth.usc.edu/emergencies/"},{"label":"Crisis Text Line","number":"Text TROJAN to 741741","note":null,"url":"https://studenthealth.usc.edu/mental-health-and-well-being/"},{"label":"988 Suicide & Crisis Lifeline","number":"988","note":null,"url":"https://studenthealth.usc.edu/mental-health-and-well-being/"},{"label":"USC emergency info line (campus-wide emergencies)","number":"(213) 740-9233","note":null,"url":"https://safety.usc.edu/resources/emergency-preparedness/"},{"label":"Housing Maintenance (24/7)","number":"(213) 740-4646","note":null,"url":"https://housing.usc.edu/index.php/csc/"},{"label":"USC Report & Response","number":"(213) 740-2500","note":null,"url":"https://dps.usc.edu/contact/"},{"label":"Office of Civil Rights Compliance (OCRC)","number":"(213) 740-5086","note":null,"url":"https://dps.usc.edu/contact/"}],"access":{"idCheck":"9 PM – 6 AM","start":"21:00","end":"06:00","after9":["g-mccarthy","g-mcclintock"],"text":"From 9 PM to 6 AM UPC operates with controlled access: only McCarthy (Figueroa at McCarthy Way) and McClintock (Jefferson at McClintock) gates are open and the campus is closed to unregistered guests. Guests must be pre-registered and show photo ID; event guests bring ID and ticket. During the day campus is open to the public, but officials may ask for USCard/photo ID at any time.","daytime":"University Park Campus is open to the public but is private property. Government photo ID is not required to enter, but university officials may ask for a USCard or photo ID at any time.","guests":"DPS After Hours Visitor Registration form (visitor.usc.edu)","prohibited":["Camping or structures for sleeping","Events/demonstrations without an approved UEPA","Amplified sound without Trojan Event Services approval","Unauthorized postings","Sticks, rods or other dangerous items"],"url":"https://dps.usc.edu/services/visitor-registration/","sources":["https://dps.usc.edu/services/visitor-registration/","https://www.usc.edu/how-to-access-campus/","https://transnet.usc.edu/index.php/about-us/entrance-hours/"]},"programs":[{"name":"TrojansAlert","text":"USC emergency notification system: real-time texts and emails from authorized officials with instructions. Automatically enrolled; keep contact info current in Experience USC. usc.edu addresses cannot opt out of legally required alerts.","url":"https://dps.usc.edu/services/trojans-alerts/"},{"name":"LiveSafe","text":"Free USC safety app managed by DPS and USC Emergency Planning. One-touch calls to DPS or 911; Anonymous messaging (suspicious activity, crimes in progress); SafeWalk virtual escort by friends/family.","url":"https://dps.usc.edu/services/safety-app/"},{"name":"Free USC Lyft","text":"Free USC Lyft Shared rides 7 PM-2 AM daily inside the UPC geofence (HSC 5 PM-2 AM Mon-Fri). See transport.json lyft.","url":"https://transnet.usc.edu/index.php/how-to-use-lyft/"},{"name":"DPS escort (2–6 AM)","text":"From 2 AM to 6 AM DPS may be able to provide an escort within the designated boundaries (call (213) 740-6000).","url":"https://safety.usc.edu/services/"},{"name":"Blue light phones","text":"Connects directly to DPS 24-hour communications center and identifies the phone location even if you cannot speak. Use to request help or an escort, report suspicious activity or a crime. Emergencies only. Nearly 300 across UPC and HSC, including every level of every parking structure.","url":"https://dps.usc.edu/services/blue-light-phones/"},{"name":"Security Ambassadors (\"Yellow Jackets\")","text":"Unarmed security officers from Allied Universal Security, contracted by USC; bright yellow jackets. Posted on street corners in neighborhoods around campus, especially near USC-owned housing; eyes and ears of DPS with a direct line to DPS. DPS does not publish post locations or hours.","url":"https://dps.usc.edu/safety-tips/getting-around/"},{"name":"Community Service Officers","text":"Patrol USC Housing facilities from 8 PM until dawn (24 h during semester and spring breaks).","url":"https://dps.usc.edu/contact/"},{"name":"Report a crime","text":"Call DPS 24/7, use LiveSafe (anonymous option), a blue light phone, a Campus Security Authority, or Crime Stoppers. Noise complaints: (213) 740-6000.","url":"https://dps.usc.edu/contact/report/"}],"gameDay":{"clearBag":"Coliseum and Galen Center: one clear plastic/vinyl/PVC bag up to 12\" x 6\" x 12\" or a one-gallon clear storage bag, plus one small clutch; medically necessary items after inspection. (Stated on the USC Commencement clear-bag page as \"similar to the one used at USC Athletics events\"; the Athletics page itself is not on the allowlist.)","nextHomeGame":"2026-11-21 (vs. Maryland per USC Hospitality \"Beat the Terrapins\"); kickoff time not found","changes":["Lyft starts 5 h after kickoff","Weekend ICS does not run","Cashless parking, $50; Evening and Off-campus Housing permits not valid","Free shuttle Grand Ave Structure -> Pardee Way from 3 h before kickoff","Lyon Center 9am-2pm and Village Fitness 1-11pm on Nov 21"],"ticketScams":"DPS warns of football ticket scams on GroupMe; buy from trusted sources and never share a photo of your USCard.","note":"Student gate locations, gate-opening times and tailgate zones/times are published by USC Athletics (usctrojans.com), which is not on the allowlist. Current Trojan Hub claims (\"student gates open 2 hours before kickoff\", \"enter from Exposition Park\", \"tailgates on Exposition Park lawns and McCarthy Quad at 9 AM\") are unverified."},"dps":{"operates":"24 hours a day, 365 days a year; patrols ~2.5 sq mi around UPC and ~1 sq mi around HSC, including off-campus neighborhoods.","stations":[{"name":"UPC station","address":"3667 McClintock Ave, Los Angeles, CA 90089 (Parking Structure A, PSA)"},{"name":"USC Village sub-station","address":"3131 South Hoover Street, Suite 1300"},{"name":"HSC station","address":"2001 Soto Street, Los Angeles, CA 90032"}]},"caveat":"Reports to USC DPS, not proof a crime occurred. Scores describe streets at times of day, not neighborhoods or people."};

  // ---------- verified daily facts ----------
  TH.FACTS = [{"text":"USC opened in 1880 with 53 students and 10 teachers, when Los Angeles still had no paved streets or electric lights.","url":"https://www.usc.edu/we-are-usc/the-university/our-history/"},{"text":"Marion McKinley Bovard became USC’s first president in 1880.","url":"https://www.usc.edu/we-are-usc/the-university/our-history/historical-timeline/"},{"text":"Tommy Trojan was unveiled in 1930, at USC’s 50th jubilee.","url":"https://www.usc.edu/we-are-usc/the-university/our-history/historical-timeline/"},{"text":"Tommy Trojan was sculpted by Roger Noble Burnham, who modeled him on several USC football players.","url":"https://www.usc.edu/usc-traditions/"},{"text":"Tommy Trojan’s pedestal lists the ideal Trojan’s qualities: faithful, scholarly, skillful, courageous, ambitious.","url":"https://www.usc.edu/usc-traditions/"},{"text":"Traveler first appeared at USC’s 1961 home opener against Georgia Tech. Whenever USC scores, the band plays “Conquest” and Traveler gallops around the Coliseum.","url":"https://www.usc.edu/usc-traditions/"},{"text":"Traveler, not Tommy Trojan, is USC’s official mascot.","url":"https://admission.usc.edu/prospective-students/live-learn-belong/find-your-people/"},{"text":"The Traveler statue facing Tommy Trojan in Hahn Plaza was unveiled on May 4, 2010.","url":"https://www.usc.edu/usc-traditions/"},{"text":"In 1979 the Trojan Marching Band recorded the title track of Fleetwood Mac’s album Tusk, which went platinum.","url":"https://www.usc.edu/usc-traditions/"},{"text":"USC’s motto, Palmam Qui Meruit Ferat (“let whoever earns the palm bear it”), was adopted in 1908.","url":"https://www.usc.edu/usc-traditions/"},{"text":"The alma mater “All Hail” was written by Alfred F. Wesson ’24 for a 1923 student show called Campus Frolics.","url":"https://www.usc.edu/usc-traditions/"},{"text":"The California poppy, USC’s official flower, joined the university seal in 1908.","url":"https://www.usc.edu/usc-traditions/"},{"text":"USC’s teams were called the Cardinals and the Methodists before becoming the Trojans in 1912.","url":"https://www.usc.edu/we-are-usc/the-university/our-history/historical-timeline/"},{"text":"Doheny Memorial Library opened on September 12, 1932. Its full name is the Edward L. Doheny Jr. Memorial Library.","url":"https://www.usc.edu/we-are-usc/the-university/our-history/historical-timeline/"},{"text":"In 1960 John F. Kennedy spoke from the steps of Doheny Library to a first-time voter convocation.","url":"https://www.usc.edu/we-are-usc/the-university/our-history/historical-timeline/"},{"text":"The Fisher Gallery, opened in 1939, was the first museum in Los Angeles devoted only to fine art.","url":"https://www.usc.edu/we-are-usc/the-university/our-history/historical-timeline/"},{"text":"The LA Memorial Coliseum, across the street from campus, was the center of the 1932 and 1984 Olympics, and the Games return in 2028.","url":"https://www.usc.edu/we-are-usc/the-university/our-history/olympic-heritage/"},{"text":"During the 1984 Olympics, the University Park Campus became Los Angeles’ largest Olympic Village.","url":"https://www.usc.edu/we-are-usc/the-university/our-history/historical-timeline/"},{"text":"USC has produced more Olympians and overall medalists than any other university in the United States.","url":"https://www.usc.edu/we-are-usc/the-university/our-history/olympic-heritage/"},{"text":"In 1904 Emil Breitkreutz became the first USC student to compete in the Olympics, winning bronze in the 800 meters.","url":"https://www.usc.edu/we-are-usc/the-university/our-history/olympic-heritage/"},{"text":"Forty-four Trojans competed at the 2016 Rio Olympics, more than from any other American university.","url":"https://www.usc.edu/we-are-usc/the-university/our-history/historical-timeline/"},{"text":"USC Village opened in 2017 on 15 acres. It is the largest development in the history of South Los Angeles.","url":"https://village.usc.edu/"},{"text":"Hecuba, queen of Troy, was unveiled in the USC Village piazza at the Village’s grand opening in fall 2017.","url":"https://village.usc.edu/about-hecuba/"},{"text":"Leavey Library stays open 24 hours from Sunday morning to Friday night during the semester, and around the clock during finals.","url":"https://libraries.usc.edu/hours"},{"text":"USC has nearly 300 blue light emergency phones, including one on every level of every parking structure.","url":"https://dps.usc.edu/services/blue-light-phones/"}];

